def safe_name(name: str) -> bool:
    """True when name is one plain file name: not empty, no NUL, no path separators, no parent references, not absolute."""
    ex safe_name("notes.txt") == True
    ex safe_name("../secret") == False
    ex safe_name("/etc/passwd") == False
    if name.char_count() == 0:
        return False
    if name == "." or name == "..":
        return False
    if "\0" in name or "/" in name or "\\" in name or ":" in name:
        return False
    if ".." in name:
        return False
    return True

def count_safe(names: list[str]) -> int:
    """Number of names that pass safe_name. Pure: opens no files, so it needs no capability."""
    ex count_safe([]) == 0
    ex count_safe(["notes.txt", "../secret", "/etc/passwd"]) == 1
    total = 0
    for n in names:
        if safe_name(n):
            total += 1
    return total

def note_readable(name: str) -> bool uses fs:
    """True when the file name is readable through fs. fs must already be confined to the notes directory by the caller. A missing or unreadable file gives False."""
    pre safe_name(name)
    fs.read_text(name) else return False
    return True

def count_readable(names: list[str]) -> int uses fs:
    """Number of names that are safe file names and readable files inside notes. Names that are not safe are skipped and never opened. The reads happen under with fs = fs.sub("notes"). Examples that open files cannot run without fs, so the behaviour is checked by tests."""
    post out >= 0 and out <= count_safe(names)
    total = 0
    with fs = fs.sub("notes"):
        for n in names:
            if not safe_name(n):
                continue
            if note_readable(n):
                total += 1
    return total
